-- Rovia. Fresh schema; no resets or destructive changes to existing environments.
create schema if not exists extensions;
create extension if not exists postgis with schema extensions;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to anon,authenticated,service_role;
create type public.visibility as enum ('public','friends','private');
create table public.profiles(id uuid primary key references auth.users on delete cascade,username text not null unique check(username=lower(username) and username ~ '^[a-z0-9_]{3,24}$'),display_name text not null check(length(display_name) between 1 and 80),avatar_path text);
create table public.profile_details(id uuid primary key references public.profiles on delete cascade,bio text check(length(bio)<=300),visibility public.visibility not null default 'friends',visit_visibility public.visibility not null default 'friends');
create table public.categories(id text primary key,label text not null);
insert into public.categories values ('cafe','Cafeterías'),('bar','Bares'),('restaurant','Restaurantes'),('shop','Comercios'),('leisure','Ocio');
create table public.places(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),category text not null references public.categories,lat double precision not null check(lat between -90 and 90),lng double precision not null check(lng between -180 and 180),location extensions.geography(point,4326) generated always as (extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography) stored,address text,area text,phone text,website text,instagram text,opening_hours text,timezone text not null default 'America/Argentina/Buenos_Aires',price_level int check(price_level between 1 and 4),source text not null default 'OpenStreetMap',external_type text,external_id text,imported_at timestamptz,closed boolean not null default false,merged_into uuid references public.places);
create index places_geo on public.places using gist(location);
create index places_search on public.places using gin(to_tsvector('spanish',name||' '||coalesce(address,'')||' '||coalesce(area,'')));
create table public.place_sources(source text not null,external_type text not null,external_id text not null,place_id uuid not null references public.places,raw_data jsonb not null,imported_at timestamptz not null,primary key(source,external_type,external_id));
create table public.place_overrides(place_id uuid primary key references public.places,fields jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references public.profiles on delete cascade,place_id uuid not null references public.places,rating int not null check(rating between 1 and 5),comment text not null check(length(trim(comment)) between 10 and 2000),visibility public.visibility not null default 'friends',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),hidden boolean not null default false,archived boolean not null default false);
create unique index one_active_review on public.reviews(user_id,place_id) where not archived;
create index review_feed on public.reviews(created_at desc,id desc);
create table public.review_photos(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.reviews on delete cascade,path text not null unique,thumbnail_path text not null unique,hidden boolean not null default false,created_at timestamptz not null default now());
create table public.likes(user_id uuid not null default auth.uid() references public.profiles on delete cascade,review_id uuid not null references public.reviews on delete cascade,primary key(user_id,review_id));
create table public.follows(follower_id uuid not null default auth.uid() references public.profiles on delete cascade,followed_id uuid not null references public.profiles on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,followed_id),check(follower_id<>followed_id));
create table public.friendships(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles on delete cascade,recipient_id uuid not null references public.profiles on delete cascade,status text not null default 'pending' check(status in ('pending','accepted')),created_at timestamptz not null default now(),check(sender_id<>recipient_id));
create unique index friendship_pair on public.friendships(least(sender_id,recipient_id),greatest(sender_id,recipient_id));
create table public.saved_places(user_id uuid not null default auth.uid() references public.profiles on delete cascade,place_id uuid not null references public.places,created_at timestamptz not null default now(),primary key(user_id,place_id));
create table public.want_places(user_id uuid not null default auth.uid() references public.profiles on delete cascade,place_id uuid not null references public.places,created_at timestamptz not null default now(),primary key(user_id,place_id));
create table public.visits(user_id uuid not null default auth.uid() references public.profiles on delete cascade,place_id uuid not null references public.places,visited_on date,visibility public.visibility not null default 'friends',shared boolean not null default false,created_at timestamptz not null default now(),primary key(user_id,place_id));
create table public.lists(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references public.profiles,name text not null check(length(trim(name)) between 1 and 80),description text check(length(description)<=300),visibility public.visibility not null default 'private',created_at timestamptz not null default now());
create table public.list_members(list_id uuid not null references public.lists on delete cascade,user_id uuid not null references public.profiles on delete cascade,role text not null check(role in ('reader','editor')),status text not null default 'pending' check(status in ('pending','accepted')),created_at timestamptz not null default now(),primary key(list_id,user_id));
create table public.list_places(list_id uuid not null references public.lists on delete cascade,place_id uuid not null references public.places,added_by uuid not null default auth.uid() references public.profiles,created_at timestamptz not null default now(),primary key(list_id,place_id));
create table public.notification_preferences(user_id uuid primary key default auth.uid() references public.profiles on delete cascade,friendship boolean not null default true,like_review boolean not null default true,list_invite boolean not null default true,list_place boolean not null default true);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,actor_id uuid not null references public.profiles on delete cascade,kind text not null check(kind in ('friendship','friend_accepted','like_review','list_invite','list_place')),reference_id uuid,read_at timestamptz,created_at timestamptz not null default now());
create index notification_inbox on public.notifications(user_id,created_at desc);
create table public.reports(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references public.profiles,review_id uuid references public.reviews on delete set null,photo_id uuid references public.review_photos on delete set null,reason text not null check(reason in ('inappropriate','spam','misleading')),explanation text check(length(explanation)<=1000),status text not null default 'pending' check(status in ('pending','resolved','rejected')),created_at timestamptz not null default now(),check(num_nonnulls(review_id,photo_id)=1));
create table public.corrections(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references public.profiles,place_id uuid not null references public.places,fields jsonb not null check(jsonb_typeof(fields)='object'),explanation text check(length(explanation)<=1000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
create table public.moderation_audit(id uuid primary key default gen_random_uuid(),moderator_id uuid not null references public.profiles,action text not null,target_id uuid not null,reason text not null,created_at timestamptz not null default now());
create table private.moderators(user_id uuid primary key references public.profiles on delete cascade);
create table private.rate_limits(user_id uuid,operation text,window_at timestamptz not null default now(),count int not null default 1,primary key(user_id,operation));
create table private.photo_gc(path text primary key,queued_at timestamptz not null default now());

create function private.is_friend(owner uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.friendships where status='accepted' and ((sender_id=owner and recipient_id=auth.uid()) or (recipient_id=owner and sender_id=auth.uid())))$$;
create function private.audience(owner uuid,v public.visibility) returns boolean language sql stable security definer set search_path='' as $$select coalesce(owner=auth.uid() or v='public' or (v='friends' and private.is_friend(owner)),false)$$;
create function private.profile_access(owner uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce((select private.audience(id,visibility) from public.profile_details where id=owner),false)$$;
create function private.activity_access(owner uuid,v public.visibility) returns boolean language sql stable security definer set search_path='' as $$select private.profile_access(owner) and private.audience(owner,v)$$;
create function private.review_access(rid uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce((select (not hidden and not archived and private.activity_access(user_id,visibility)) or user_id=auth.uid() from public.reviews where id=rid),false)$$;
create function private.is_moderator() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.moderators where user_id=auth.uid())$$;
create function public.is_moderator() returns boolean language sql stable security invoker set search_path='' as $$select private.is_moderator()$$;
create function private.list_access(lid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.lists l where l.id=lid and (l.owner_id=auth.uid() or private.activity_access(l.owner_id,l.visibility) or exists(select 1 from public.list_members m where m.list_id=lid and m.user_id=auth.uid() and m.status='accepted')))$$;
create function private.list_owner(lid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.lists where id=lid and owner_id=auth.uid())$$;
create function private.list_editor(lid uuid) returns boolean language sql stable security definer set search_path='' as $$select private.list_owner(lid) or exists(select 1 from public.list_members where list_id=lid and user_id=auth.uid() and status='accepted' and role='editor')$$;
create function private.check_rate(op text,maximum int default 30) returns void language plpgsql security definer set search_path='' as $$declare n int;begin if auth.uid() is null then raise exception 'Iniciá sesión';end if;insert into private.rate_limits(user_id,operation) values(auth.uid(),op) on conflict(user_id,operation) do update set count=case when private.rate_limits.window_at<now()-interval '1 minute' then 1 else private.rate_limits.count+1 end,window_at=case when private.rate_limits.window_at<now()-interval '1 minute' then now() else private.rate_limits.window_at end returning count into n;if n>maximum then raise exception 'Demasiados intentos. Esperá un minuto.';end if;end$$;
create function private.new_user() returns trigger language plpgsql security definer set search_path='' as $$declare un text;dn text;begin un:=lower(new.raw_user_meta_data->>'username');dn:=trim(new.raw_user_meta_data->>'display_name');if un is null or un !~ '^[a-z0-9_]{3,24}$' or dn is null or length(dn) not between 1 and 80 then raise exception 'Nombre o usuario inválido';end if;insert into public.profiles(id,username,display_name) values(new.id,un,dn);insert into public.profile_details(id) values(new.id);insert into public.notification_preferences(user_id) values(new.id);return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.new_user();
create function private.touch_review() returns trigger language plpgsql set search_path='' as $$begin new.updated_at:=now();return new;end$$;
create trigger touch_review before update on public.reviews for each row execute function private.touch_review();
create function private.enforce_photo_limit() returns trigger language plpgsql security definer set search_path='' as $$begin perform 1 from public.reviews where id=new.review_id for update;if (select count(*) from public.review_photos where review_id=new.review_id)>=5 then raise exception 'Máximo cinco fotos';end if;return new;end$$;
create trigger photo_limit before insert on public.review_photos for each row execute function private.enforce_photo_limit();
create function private.queue_photo_delete() returns trigger language plpgsql security definer set search_path='' as $$begin insert into private.photo_gc(path) values(old.path),(old.thumbnail_path) on conflict do nothing;return old;end$$;
create trigger gc_photo after delete on public.review_photos for each row execute function private.queue_photo_delete();
create function private.notify(target uuid,actor uuid,k text,ref uuid) returns void language plpgsql security definer set search_path='' as $$declare enabled boolean;begin if target=actor then return;end if;select case k when 'friendship' then friendship when 'friend_accepted' then friendship when 'like_review' then like_review when 'list_invite' then list_invite when 'list_place' then list_place else false end into enabled from public.notification_preferences where user_id=target;if enabled then insert into public.notifications(user_id,actor_id,kind,reference_id) values(target,actor,k,ref);end if;end$$;
create function private.notify_action() returns trigger language plpgsql security definer set search_path='' as $$declare target uuid;begin if TG_TABLE_NAME='likes' then select user_id into target from public.reviews where id=new.review_id;perform private.notify(target,new.user_id,'like_review',new.review_id);elsif TG_TABLE_NAME='list_members' then perform private.notify(new.user_id,auth.uid(),'list_invite',new.list_id);elsif TG_TABLE_NAME='list_places' then for target in select owner_id from public.lists where id=new.list_id union select user_id from public.list_members where list_id=new.list_id and status='accepted' loop perform private.notify(target,new.added_by,'list_place',new.list_id);end loop;end if;return new;end$$;
create trigger like_notification after insert on public.likes for each row execute function private.notify_action();
create trigger invitation_notification after insert on public.list_members for each row execute function private.notify_action();
create trigger addition_notification after insert on public.list_places for each row execute function private.notify_action();
create function private.notification_access(n public.notifications) returns boolean language sql stable security definer set search_path='' as $$select n.user_id=auth.uid() and case when n.kind='like_review' then private.review_access(n.reference_id) when n.kind='list_place' then private.list_access(n.reference_id) when n.kind='list_invite' then exists(select 1 from public.list_members where list_id=n.reference_id and user_id=auth.uid()) else exists(select 1 from public.friendships where id=n.reference_id and (sender_id=auth.uid() or recipient_id=auth.uid())) end$$;

-- Authenticated APIs. Transactions prevent crossed invitations from granting friendship.
create function public.friend_action(target uuid,action text) returns void language plpgsql security definer set search_path='' as $$declare r public.friendships;begin perform private.check_rate('friendship');if target=auth.uid() then raise exception 'No podés agregarte';end if;perform pg_advisory_xact_lock(hashtextextended(least(auth.uid(),target)::text||greatest(auth.uid(),target)::text,0));select * into r from public.friendships where least(sender_id,recipient_id)=least(auth.uid(),target) and greatest(sender_id,recipient_id)=greatest(auth.uid(),target) for update;if action='request' then if r.id is null then insert into public.friendships(sender_id,recipient_id) values(auth.uid(),target) returning * into r;perform private.notify(target,auth.uid(),'friendship',r.id);end if;elsif action='accept' then if r.recipient_id<>auth.uid() or r.status<>'pending' or r.id is null then raise exception 'Solicitud no disponible';end if;update public.friendships set status='accepted' where id=r.id;perform private.notify(r.sender_id,auth.uid(),'friend_accepted',r.id);elsif action in ('cancel','reject','remove') then if r.id is null then return;end if;if (action='cancel' and r.sender_id<>auth.uid()) or (action='reject' and r.recipient_id<>auth.uid()) or (action='remove' and r.status<>'accepted') then raise exception 'Acción no autorizada';end if;delete from public.friendships where id=r.id;else raise exception 'Acción inválida';end if;end$$;
create function public.member_action(lid uuid,target uuid,action text,new_role text default 'reader') returns void language plpgsql security definer set search_path='' as $$begin perform private.check_rate('member');perform 1 from public.lists where id=lid for update;if action in ('invite','role','remove') then if not private.list_owner(lid) then raise exception 'Solo el propietario administra miembros';end if;if exists(select 1 from public.lists where id=lid and owner_id=target) then raise exception 'El propietario no puede ser invitado';end if;if new_role not in ('reader','editor') then raise exception 'Rol inválido';end if;if action='invite' then insert into public.list_members(list_id,user_id,role) values(lid,target,new_role) on conflict do nothing;elsif action='role' then update public.list_members set role=new_role where list_id=lid and user_id=target;else delete from public.list_members where list_id=lid and user_id=target;end if;elsif action in ('accept','reject','leave') and target=auth.uid() then if action='accept' then update public.list_members set status='accepted' where list_id=lid and user_id=auth.uid() and status='pending';else delete from public.list_members where list_id=lid and user_id=auth.uid();end if;else raise exception 'Acción no autorizada';end if;end$$;
create function public.mark_visit(pid uuid,day date default null,audience public.visibility default 'friends',share boolean default false,clear_pending boolean default true) returns void language plpgsql security definer set search_path='' as $$begin perform private.check_rate('visit');insert into public.visits(user_id,place_id,visited_on,visibility,shared) values(auth.uid(),pid,day,audience,share) on conflict(user_id,place_id) do update set visited_on=excluded.visited_on,visibility=excluded.visibility,shared=excluded.shared;if clear_pending then delete from public.want_places where user_id=auth.uid() and place_id=pid;end if;end$$;
create function public.profile_get(uid uuid) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',p.id,'username',p.username,'display_name',p.display_name,'avatar_path',p.avatar_path,'visibility',d.visibility,'visit_visibility',case when private.profile_access(p.id) then d.visit_visibility end,'bio',case when private.profile_access(p.id) then d.bio end,'accessible',private.profile_access(p.id),'followers',case when private.profile_access(p.id) then (select count(*) from public.follows where followed_id=p.id) end,'following',case when private.profile_access(p.id) then (select count(*) from public.follows where follower_id=p.id) end,'friends',case when private.profile_access(p.id) then (select count(*) from public.friendships where status='accepted' and (sender_id=p.id or recipient_id=p.id)) end) from public.profiles p join public.profile_details d on d.id=p.id where p.id=uid$$;
create function public.public_rating(pid uuid) returns table(rating numeric,review_count bigint) language sql stable security definer set search_path='' as $$select round(avg(r.rating),1),count(*) from public.reviews r join public.profile_details d on d.id=r.user_id where r.place_id=pid and r.visibility='public' and d.visibility='public' and not r.hidden and not r.archived$$;
create function public.search_places(south float8,west float8,north float8,east float8,center_lat float8,center_lng float8,search text default '',cats text[] default '{}',min_rating numeric default 0,price int default null,radius int default null) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select p.*,pr.rating,pr.review_count,extensions.st_distance(p.location,extensions.st_setsrid(extensions.st_makepoint(center_lng,center_lat),4326)::extensions.geography) distance_m from public.places p cross join lateral public.public_rating(p.id) pr where p.merged_into is null and not p.closed and p.location operator(extensions.&&) extensions.st_makeenvelope(west,south,east,north,4326)::extensions.geography and (search='' or concat_ws(' ',p.name,p.address,p.area,p.category,(select label from public.categories where id=p.category)) ilike '%'||left(search,100)||'%') and (cardinality(cats)=0 or p.category=any(cats)) and (min_rating=0 or pr.rating>=min_rating) and (price is null or p.price_level=price) and (radius is null or extensions.st_dwithin(p.location,extensions.st_setsrid(extensions.st_makepoint(center_lng,center_lat),4326)::extensions.geography,radius)) order by distance_m,p.id limit 200) x$$;
create function public.feed_page(mode text default 'all',before_time timestamptz default null,before_id uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select r.*,jsonb_build_object('id',p.id,'display_name',p.display_name,'username',p.username) profiles,jsonb_build_object('id',l.id,'name',l.name,'category',l.category) places from public.reviews r join public.profiles p on p.id=r.user_id join public.places l on l.id=r.place_id where not r.hidden and not r.archived and (before_time is null or (r.created_at,r.id)<(before_time,before_id)) and ((mode in ('all','friends') and private.is_friend(r.user_id)) or (mode in ('all','following') and exists(select 1 from public.follows where follower_id=auth.uid() and followed_id=r.user_id))) order by r.created_at desc,r.id desc limit 20) x$$;
create function public.visit_feed(mode text default 'all',before_time timestamptz default null,before_user uuid default null,before_place uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select v.*,jsonb_build_object('id',p.id,'display_name',p.display_name,'username',p.username) profiles,jsonb_build_object('id',l.id,'name',l.name,'category',l.category) places from public.visits v join public.profiles p on p.id=v.user_id join public.places l on l.id=v.place_id where v.shared and (before_time is null or (v.created_at,v.user_id,v.place_id)<(before_time,before_user,before_place)) and ((mode in ('all','friends') and private.is_friend(v.user_id)) or (mode in ('all','following') and exists(select 1 from public.follows where follower_id=auth.uid() and followed_id=v.user_id))) order by v.created_at desc,v.user_id desc,v.place_id desc limit 20) x$$;
-- Import raw data; approved overlays win. Only service_role can invoke.
create function public.import_places(batch jsonb) returns void language plpgsql security definer set search_path='' as $$declare x jsonb;o jsonb;pid uuid;begin if jsonb_array_length(batch)>100 then raise exception 'Lote demasiado grande';end if;for x in select value from jsonb_array_elements(batch) loop select place_id into pid from public.place_sources where source='OpenStreetMap' and external_type=x->>'external_type' and external_id=x->>'external_id';if pid is null then pid:=(x->>'id')::uuid;end if;if exists(select 1 from public.places where id=(x->>'id')::uuid and merged_into is not null) then update public.place_sources set raw_data=x,imported_at=(x->>'imported_at')::timestamptz where source='OpenStreetMap' and external_type=x->>'external_type' and external_id=x->>'external_id';continue;end if;select fields into o from public.place_overrides where place_id=pid;o:=coalesce(o,'{}');insert into public.places(id,name,category,lat,lng,address,area,phone,website,instagram,opening_hours,timezone,price_level,source,external_type,external_id,imported_at,closed) values(pid,x->>'name',case when o?'category' then o->>'category' else x->>'category' end,(x->>'lat')::float8,(x->>'lng')::float8,case when o?'address' then o->>'address' else x->>'address' end,x->>'area',case when o?'phone' then o->>'phone' else x->>'phone' end,case when o?'website' then o->>'website' else x->>'website' end,case when o?'instagram' then o->>'instagram' else x->>'instagram' end,case when o?'opening_hours' then o->>'opening_hours' else x->>'opening_hours' end,x->>'timezone',null,'OpenStreetMap',x->>'external_type',x->>'external_id',(x->>'imported_at')::timestamptz,coalesce((o->>'closed')::boolean,false)) on conflict(id) do update set name=excluded.name,category=excluded.category,lat=excluded.lat,lng=excluded.lng,address=excluded.address,area=excluded.area,phone=excluded.phone,website=excluded.website,instagram=excluded.instagram,opening_hours=excluded.opening_hours,imported_at=excluded.imported_at;insert into public.place_sources values('OpenStreetMap',x->>'external_type',x->>'external_id',pid,x,(x->>'imported_at')::timestamptz) on conflict(source,external_type,external_id) do update set raw_data=excluded.raw_data,imported_at=excluded.imported_at;end loop;end$$;

-- RLS, including raw API paths. Never depend on hidden UI controls.
do $$declare t text;begin foreach t in array array['profiles','profile_details','categories','places','place_sources','place_overrides','reviews','review_photos','likes','follows','friendships','saved_places','want_places','visits','lists','list_members','list_places','notification_preferences','notifications','reports','corrections','moderation_audit'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end$$;
grant select on public.profiles,public.categories,public.places,public.place_sources,public.place_overrides,public.reviews,public.review_photos,public.likes,public.profile_details,public.lists,public.list_members,public.list_places,public.visits to anon,authenticated;
grant select on public.follows,public.friendships,public.saved_places,public.want_places,public.notification_preferences,public.notifications,public.reports,public.corrections,public.moderation_audit to authenticated;
grant update(username,display_name) on public.profiles to authenticated;
grant update(bio,visibility,visit_visibility) on public.profile_details to authenticated;
grant insert(user_id,place_id,rating,comment,visibility) on public.reviews to authenticated;
grant update(rating,comment,visibility) on public.reviews to authenticated;
grant delete on public.reviews to authenticated;
grant insert(user_id,review_id),delete on public.likes to authenticated;
grant insert(follower_id,followed_id),delete on public.follows to authenticated;
grant insert(user_id,place_id),delete on public.saved_places,public.want_places to authenticated;
grant delete on public.visits to authenticated;
grant insert(owner_id,name,description,visibility),update(name,description,visibility),delete on public.lists to authenticated;
grant insert(list_id,place_id,added_by),delete on public.list_places to authenticated;
grant update(friendship,like_review,list_invite,list_place) on public.notification_preferences to authenticated;
grant update(read_at) on public.notifications to authenticated;
grant insert(user_id,review_id,photo_id,reason,explanation) on public.reports to authenticated;
grant insert(user_id,place_id,fields,explanation) on public.corrections to authenticated;
create policy profiles_read on public.profiles for select using(true);
create policy profiles_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy details_read on public.profile_details for select using(private.profile_access(id));
create policy details_update on public.profile_details for update using(id=auth.uid()) with check(id=auth.uid());
create policy categories_read on public.categories for select using(true);
create policy places_read on public.places for select using(true);
create policy sources_read on public.place_sources for select using(true);
create policy overlays_read on public.place_overrides for select using(true);
create policy review_read on public.reviews for select using(user_id=auth.uid() or (not hidden and not archived and private.activity_access(user_id,visibility)));
create policy review_insert on public.reviews for insert with check(user_id=auth.uid() and exists(select 1 from public.places where id=place_id and merged_into is null));
create policy review_update on public.reviews for update using(user_id=auth.uid() and not archived) with check(user_id=auth.uid());
create policy review_delete on public.reviews for delete using(user_id=auth.uid());
create policy photo_read on public.review_photos for select using((not hidden and private.review_access(review_id)) or (private.is_moderator() and (hidden or exists(select 1 from public.reports where status='pending' and (photo_id=review_photos.id or review_id=review_photos.review_id)))));
create policy like_read on public.likes for select using(private.review_access(review_id));
create policy like_insert on public.likes for insert with check(user_id=auth.uid() and private.review_access(review_id));
create policy like_delete on public.likes for delete using(user_id=auth.uid());
create policy follow_read on public.follows for select using(follower_id=auth.uid() or followed_id=auth.uid() or (private.profile_access(follower_id) and private.profile_access(followed_id)));
create policy follow_insert on public.follows for insert with check(follower_id=auth.uid());
create policy follow_delete on public.follows for delete using(follower_id=auth.uid());
create policy friends_read on public.friendships for select using(sender_id=auth.uid() or recipient_id=auth.uid() or (status='accepted' and private.profile_access(sender_id) and private.profile_access(recipient_id)));
create policy saved_read on public.saved_places for select using(user_id=auth.uid());
create policy saved_insert on public.saved_places for insert with check(user_id=auth.uid());
create policy saved_delete on public.saved_places for delete using(user_id=auth.uid());
create policy want_read on public.want_places for select using(user_id=auth.uid());
create policy want_insert on public.want_places for insert with check(user_id=auth.uid());
create policy want_delete on public.want_places for delete using(user_id=auth.uid());
create policy visits_read on public.visits for select using(private.activity_access(user_id,visibility) and exists(select 1 from public.profile_details where id=user_id and private.audience(user_id,visit_visibility)));
create policy visits_delete on public.visits for delete using(user_id=auth.uid());
create policy lists_read on public.lists for select using(owner_id=auth.uid() or private.list_access(id));
create policy lists_insert on public.lists for insert with check(owner_id=auth.uid());
create policy lists_update on public.lists for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy lists_delete on public.lists for delete using(owner_id=auth.uid());
create policy members_read on public.list_members for select using(user_id=auth.uid() or private.list_access(list_id));
create policy list_places_read on public.list_places for select using(private.list_access(list_id));
create policy list_places_insert on public.list_places for insert with check(added_by=auth.uid() and private.list_editor(list_id));
create policy list_places_delete on public.list_places for delete using(private.list_editor(list_id));
create policy prefs_read on public.notification_preferences for select using(user_id=auth.uid());
create policy prefs_update on public.notification_preferences for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notifications_read on public.notifications for select using(private.notification_access(notifications));
create policy notifications_update on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy reports_read on public.reports for select using(user_id=auth.uid() or private.is_moderator());
create policy reports_insert on public.reports for insert with check(user_id=auth.uid() and (private.review_access(review_id) or exists(select 1 from public.review_photos where id=photo_id)));
create policy corrections_read on public.corrections for select using(user_id=auth.uid() or private.is_moderator());
create policy corrections_insert on public.corrections for insert with check(user_id=auth.uid());
create policy audit_read on public.moderation_audit for select using(private.is_moderator());

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('review-photos','review-photos',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy authorized_photo_read on storage.objects for select using(bucket_id='review-photos' and exists(select 1 from public.review_photos p where (p.path=name or p.thumbnail_path=name) and ((not p.hidden and private.review_access(p.review_id)) or (private.is_moderator() and (p.hidden or exists(select 1 from public.reports where status='pending' and (photo_id=p.id or review_id=p.review_id)))))));
-- Only the image edge function (service_role) writes Storage and photo metadata.
-- All functions default to public EXECUTE in PG; explicitly close them.
revoke execute on all functions in schema public from public,anon,authenticated;
revoke execute on all functions in schema private from public,anon,authenticated;
grant execute on function private.is_friend(uuid),private.audience(uuid,public.visibility),private.profile_access(uuid),private.activity_access(uuid,public.visibility),private.review_access(uuid),private.list_access(uuid),private.list_owner(uuid),private.list_editor(uuid),private.is_moderator(),private.notification_access(public.notifications) to anon,authenticated;
grant execute on function public.profile_get(uuid),public.public_rating(uuid),public.search_places(float8,float8,float8,float8,float8,float8,text,text[],numeric,int,int) to anon,authenticated;
grant execute on function public.is_moderator(),public.friend_action(uuid,text),public.member_action(uuid,uuid,text,text),public.mark_visit(uuid,date,public.visibility,boolean,boolean),public.feed_page(text,timestamptz,uuid),public.visit_feed(text,timestamptz,uuid,uuid) to authenticated;
grant execute on function public.import_places(jsonb) to service_role;
grant all on all tables in schema public,private to service_role;
grant execute on all functions in schema private to service_role;
